select case when a.balance >= 63000 then 'high' when a.balance >= 18000 then 'mid' else 'low' end as balance_bucket, round(stddev(t.amount), 2) as stddev_amount, sum(case when t.txn_type = 'FEE' then 1 else 0 end) as fee_count from transactions t inner join accounts a on t.account_id = a.id full outer join customers c on a.customer_id = c.id where c.country = 'TH' group by case when a.balance >= 63000 then 'high' when a.balance >= 18000 then 'mid' else 'low' end
